select extensions.is(pg_temp.op('personal_plans','cccccccc-cccc-4ccc-8ccc-cccccccccccc','0','{"source":"advanced","schema_version":1,"level_band":"3.0–3.5","plan_snapshot":{"id":"PU31-20260101100000-1","version":"3.1","createdAt":"2026-01-01T10:00:00Z","level":"3.0–3.5","scores":{"third":12,"reset":13,"movement":14,"counter":15,"doubles":16,"decision":17},"exercises":[{"id":"ADV-PU-037","week":37,"advanced":true,"focus":"third-drop","metric":"third","skill":"strategy","skillName":"Third-shot drop","name":"Drop thuận tay từ giữa cuối sân","setup":"Từ baseline, bạn tập trả sâu vào giữa; đánh quả thứ ba mềm tới kitchen chéo. Thiết bị: vợt, 6–12 bóng, 2 nón đánh dấu mềm.","instructions":"Đánh 10 quả cùng điểm tiếp xúc thuận tay. Tập ba hiệp có nghỉ ngắn, ưu tiên chất lượng bóng.","measure":"Ít nhất 12/20 cú drop hợp lệ rơi trong kitchen. Đây là chỉ tiêu nội bộ để chọn giáo án, không phải chứng nhận trình độ.","mistake":"Đánh drop quá cao khiến đối thủ volley tấn công. · Cố tiến lên trước khi xác định quỹ đạo bóng. · Bỏ qua quy tắc hai lần nảy sau giao bóng.","minutes":12,"baseline":12,"target":15},{"id":"ADV-PU-038","week":38,"advanced":true,"focus":"transition-reset","metric":"reset","skill":"position","skillName":"Reset & transition","name":"Reset bóng thấp từ vùng giữa sân","setup":"Hai người đứng đối diện; người tập ở vùng giữa sân, người đưa bóng gần kitchen. Thiết bị: vợt, 6–12 bóng, 2 nón đánh dấu mềm.","instructions":"Đổi bóng sang thuận tay/trái tay mỗi 5 lượt. Chia thành bốn lượt, mỗi lượt năm tình huống.","measure":"Ít nhất 12/20 reset rơi gần kitchen đối thủ. Đây là chỉ tiêu nội bộ để chọn giáo án, không phải chứng nhận trình độ.","mistake":"Đứng cứng chân và đánh bật bóng quá cao. · Chạy lên lưới khi bóng đối phương đang tới. · Đánh volley khi đang chạm kitchen hoặc vạch kitchen.","minutes":12,"baseline":13,"target":16},{"id":"ADV-PU-043","week":43,"advanced":true,"focus":"transition-reset","metric":"movement","skill":"position","skillName":"Di chuyển chuyển tiếp","name":"Reset khi di chuyển từ baseline","setup":"Vạch đường tiến từ cuối sân tới kitchen với một điểm dừng ở giữa. Thiết bị: vợt, 6–12 bóng, 2 nón đánh dấu mềm.","instructions":"Chơi 5 pha chuyển tiếp, ưu tiên không lao quá đà. Chơi ba lượt, mỗi lượt năm phút; đổi vai khi phù hợp.","measure":"Ít nhất 12/20 cú reset hợp lệ trong di chuyển. Đây là chỉ tiêu nội bộ để chọn giáo án, không phải chứng nhận trình độ.","mistake":"Đứng cứng chân và đánh bật bóng quá cao. · Chạy lên lưới khi bóng đối phương đang tới. · Đánh volley khi đang chạm kitchen hoặc vạch kitchen.","minutes":15,"baseline":14,"target":17}],"matchFocus":null,"checkpoint":{"skill":"third","baseline":12,"target":15,"attempts":20},"minutes":{"warmup":10,"drills":[12,12,15],"assessment":6,"cooldown":5},"completedAt":null,"checkScore":null}}'::jsonb)->>'status','applied','advanced plan from existing core accepted');
